static U8 rconhi;



void updateroundkey(void)
{

  // update keybuf with next 4 words
  aes_keybuf[0] ^= (subb[aes_keybuf[13]] ^ rconhi);
  aes_keybuf[1] ^= subb[aes_keybuf[14]];
  aes_keybuf[2] ^= subb[aes_keybuf[15]];
  aes_keybuf[3] ^= subb[aes_keybuf[12]];

  memxor(aes_keybuf+4,aes_keybuf,AES_SIZE-4); // simple xor for the rest
  
  // update round constant for next time (multiply by 2 mod AES_POLY)
  if(rconhi & 0x80)
    rconhi = (rconhi<<1) ^ AES_POLY;
  else
    rconhi<<=1;
}

// we don't use a pre-made key expansion buffer.  instead we just do key expansion incrementally as we need it.
void addroundkey(void)
{
  memxor(aes_state,aes_keybuf,AES_SIZE);  // add current key into state
  updateroundkey();

}

// subbytes() and shiftrows() performed together.  faster and shorter.
void subshift(void)
{
U8 i,j;
	for(j=0,i=0;i<AES_SIZE;j=((j+5) & (AES_SIZE-1)),i++)
	{
		aes_state[AES_SIZE+i] = subb[aes_state[j]]; // store result in 2nd half
	}
}

// MixColumns() algoritm, re-written without multiplication routines or tables!
void mixcols(void)
{
U8 d[4];
U8 *p;
U8 *q;
U8 j;
U8 x;

	for(p=aes_state+AES_SIZE,q=aes_state;q<aes_state+AES_SIZE;q+=4,p+=4)
	{
		// fill array d with aes_double of each element of "column"
		for(j=0;j<4;j++)
		{
			x = (p[j] & 0x80) ? AES_POLY : 0;
			d[j] = (p[j]<<1) ^ x;
		}

		// compute 4 elements of column vector, storing back into 1st half of state
		q[0] = d[0] ^ p[1] ^ d[1] ^ p[2] ^ p[3]; // [2]*0 [3]*1 [1]*2 [1]*3
		q[1] = d[1] ^ p[2] ^ d[2] ^ p[3] ^ p[0]; // [2]*1 [3]*2 [1]*3 [1]*0
		q[2] = d[2] ^ p[3] ^ d[3] ^ p[0] ^ p[1]; // [2]*2 [3]*3 [1]*0 [1]*1
		q[3] = d[3] ^ p[0] ^ d[0] ^ p[1] ^ p[2]; // [2]*3 [3]*0 [1]*1 [1]*2
	}
}

// encrypt state data in place, using key in keybuf (consumed)
void aes128(void)
{
  rconhi = 1;  // 2^0
  addroundkey();
  while(rconhi != 0xd8) // 2^10
  {
	  subshift(); // SubBytes() and ShiftRows() to 2nd half of state
	  if(rconhi==0x6c) // 2^9
		  memcpy(aes_state,aes_state+AES_SIZE,AES_SIZE); // no mixcols() in last round
	  else
		  mixcols(); 
	  addroundkey();
  }
}

void aes_encrypt(U8 *key,U8 *plain, U8 *cipher)
{
  memcpy(aes_keybuf,key,AES_SIZE);	// copy key to aes_keybuf, which gets consumed
  memcpy(aes_state,plain,AES_SIZE);	// copy data to 1st half of state buffer
  aes128();						// encrypt in place
  memcpy(cipher,aes_state,AES_SIZE);  // copy encrypted to user output buffer
}


