U8 mulmod(U8 a,U8 b)
{
unsigned x;
	if(a==0 || b==0)
		return 0;
	x = lmod[a];
	x += lmod[b];
	if(x >= 255)
		x -= 255;
	return amod[x];
}

U8 halfmod(U8 a)
{
unsigned x;
	if(a==0)
		return 0;
	x = lmod[a];
	x += 0xe6;  // 0xe6 == lmod[0x8d]
	if(x >= 255)
		x -= 255;
	return amod[x];
}



U8 invmod(U8 a)
{
	if(a==0)
		return 0;
	return amod[255-lmod[a]];
}

// subbytes() and shiftrows() performed together.  faster and shorter.
void inv_subshift(void)
{
U8 i,j;
	for(j=0,i=0;i<AES_SIZE;j=((j+5) & (AES_SIZE-1)),i++)
	{
		aes_state[j] = inv_subb[aes_state[AES_SIZE+i]]; // store result in 2nd half
	}
}
// invMixColumns() algoritm, re-written without multiplication routines or tables!
#define K0 0xE
#define K1 0xB
#define K2 0xD
#define K3 0x9

void inv_mixcols(void)
{
U8 *p;
U8 *q;
U8 j;

	for(p=aes_state,q=aes_state+AES_SIZE;p<aes_state+AES_SIZE;q+=4,p+=4)
	{
		// compute 4 elements of column vector, storing into 2nd half of state
		for(j=0;j<4;j++)
		{
			q[j] = mulmod(p[j],K0) ^ mulmod(p[(j+1)&3],K1) ^ mulmod(p[(j+2)&3],K2) ^ mulmod(p[(j+3)&3],K3);
		}
	}
}



// we don't use a pre-made key expansion buffer.  instead we just do key expansion incrementally as we need it.
void inv_addroundkey(void)
{
U8 i;

  // update round constant for next time (multiply by inv_2 mod AES_POLY)
  rconhi = halfmod(rconhi); // multiply by 0x8d == invmod(2) 

  for(i=15;i>=4;i--)
  {
	  aes_keybuf[i] ^= aes_keybuf[i-4];
  }

  // update keybuf with next 4 words
  aes_keybuf[3] ^= subb[aes_keybuf[12]];
  aes_keybuf[2] ^= subb[aes_keybuf[15]];
  aes_keybuf[1] ^= subb[aes_keybuf[14]];
  aes_keybuf[0] ^= (subb[aes_keybuf[13]] ^ rconhi);

  memxor(aes_state,aes_keybuf,AES_SIZE);  // add current key into state
  
}



void inv_aes128(void)
{
	rconhi = 0xd8; // 2^10
	inv_addroundkey();
	while(rconhi != 1) // == 2^0 ?
	{
		if(rconhi==0x6c)  // 2^9
			memcpy(aes_state+AES_SIZE,aes_state,AES_SIZE); // no inv_mixcols in 1st rouund
		else
			inv_mixcols();
		inv_subshift();
		inv_addroundkey();
	}
}

void inv_aes128_setup(void)
{
	rconhi = 1; // 2^0
	while(rconhi != 0xd8) // 2^10
		updateroundkey();
}

// this routine is substantially slower than aes_encrypt(), because:
// 1) the encryption key must be heavily processed each time before we start decrypting
// 2) the inverse mix columns is not as speed-optimized as the mix columns was.
// but we can accept this poorer performance because our application does very little decryption.
// it still costs a fair amount of code space.

void aes_decrypt(U8 *key, U8 *cipher,U8 *plain)
{
	memcpy(aes_keybuf,key,AES_SIZE);
	inv_aes128_setup();  // prepare to go backwards
	memcpy(aes_state,cipher,AES_SIZE);
	inv_aes128();
	memcpy(plain,aes_state,AES_SIZE);
}


